import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve, sep } from "node:path";
import { env } from "../../config/env.ts";

/** Where artifact bytes live. The DB (`artifacts`) holds metadata + sha256; this holds content. */
export interface BlobStore {
  put(key: string, body: Uint8Array): Promise<void>;
  /** null when the key doesn't exist. */
  get(key: string): Promise<Uint8Array | null>;
}

/** Keys are generated by us (org/<uuid>/<kind>/<uuid>.<ext>); anything else is rejected. */
const KEY = /^[a-z0-9_-]+(\/[a-z0-9_.-]+)+$/i;
function assertKey(key: string) {
  if (!KEY.test(key) || key.includes("..")) throw new Error("Invalid storage key");
}

export function createFsBlobStore(root: string): BlobStore {
  const base = resolve(root);
  const pathFor = (key: string) => {
    assertKey(key);
    const p = resolve(base, key);
    if (!p.startsWith(base + sep)) throw new Error("Invalid storage key");
    return p;
  };
  return {
    async put(key, body) {
      const p = pathFor(key);
      await mkdir(dirname(p), { recursive: true });
      // wx: never overwrite (keys are unique; artifacts are immutable evidence).
      await writeFile(p, body, { flag: "wx", mode: 0o600 });
    },
    async get(key) {
      try {
        return new Uint8Array(await readFile(pathFor(key)));
      } catch (e) {
        if ((e as NodeJS.ErrnoException).code === "ENOENT") return null;
        throw e;
      }
    },
  };
}

export function createMemoryBlobStore(): BlobStore {
  const blobs = new Map<string, Uint8Array>();
  return {
    async put(key, body) {
      assertKey(key);
      if (blobs.has(key)) throw new Error("Blob already exists");
      blobs.set(key, body);
    },
    async get(key) {
      return blobs.get(key) ?? null;
    },
  };
}

export const blobStore: BlobStore =
  env.STORAGE_DRIVER === "memory" ? createMemoryBlobStore() : createFsBlobStore(env.STORAGE_DIR);
